// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** An entry of the hospital's list of what to report (MSDS CQI 106 i). */
export interface IncidentTypeOut {
  type_code: string;
  name: string;
  area: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational";
  /** Always: a sentinel event whenever it happened; IfSevereHarm: only with severe harm or a death */
  sentinel: "Always" | "IfSevereHarm";
  description: string | null;
  sort_order: number;
  is_active: boolean;
  row_version: number;
}

export interface IncidentTypeIn {
  type_code: string;
  name: string;
  area: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational";
  /** Always: a sentinel event whenever it happens; IfSevereHarm: only with severe harm or a death */
  sentinel?: "Always" | "IfSevereHarm";
  /** What to report under it (the printed list) */
  description?: string | null;
  sort_order?: number;
}

export interface IncidentTypeUpdateIn {
  name?: string | null;
  sentinel?: "Always" | "IfSevereHarm" | null;
  description?: string | null;
  sort_order?: number | null;
  /** False: no longer reported under it (past incidents keep it) */
  is_active?: boolean | null;
  /** Optimistic concurrency: the row_version you loaded */
  expected_version?: number | null;
}

/** What to report: the incident types — GET /api/v1/incident-types (who may call: any logged-in user). */
export function listTypes(query?: { area?: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational" | null; active_only?: boolean }): Promise<IncidentTypeOut[]> {
  return api<IncidentTypeOut[]>("GET", withQuery(`/incident-types`, query), undefined);
}

/** Add an incident type — POST /api/v1/incident-types (who may call: holders of incident.manage). */
export function createType(body: IncidentTypeIn): Promise<IncidentTypeOut> {
  return api<IncidentTypeOut>("POST", `/incident-types`, body, { idempotent: true });
}

/** Change or retire an incident type — PATCH /api/v1/incident-types/{type_code} (who may call: holders of incident.manage). */
export function updateType(type_code: string, body: IncidentTypeUpdateIn): Promise<IncidentTypeOut> {
  return api<IncidentTypeOut>("PATCH", `/incident-types/${type_code}`, body);
}

/** The list of sentinel events and how to report (PDF) — GET /api/v1/incidents/sentinel-list/pdf (who may call: any logged-in user). */
export function sentinelListPdf(): Promise<unknown> {
  return api<unknown>("GET", `/incidents/sentinel-list/pdf`, undefined);
}
